        try:
            dtypes = array.dtypes
            # dtypes is a Series for DataFrames
            if hasattr(dtypes, 'iloc'):
                if len(dtypes) == 1:
                    dtype_orig = dtypes.iloc[0]
                else:
                    unique_dtypes = set(dtypes)
                    if len(unique_dtypes) == 1:
                        dtype_orig = unique_dtypes.pop()
                    elif any(getattr(dt, 'kind', None) == 'O'
                             for dt in dtypes):
